import{d as g,C as t,o as h,c as d,j as a,a as i,E as r,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"荀子·第1篇·劝学","description":"《荀子·劝学》——学习如何改变人，怎样积累、专一并落实于行为。","frontmatter":{"title":"荀子·第1篇·劝学","description":"《荀子·劝学》——学习如何改变人，怎样积累、专一并落实于行为。","category":"guide","aliases":["荀子劝学","荀子第1篇"],"source":["维基文库《荀子/勸學篇》，修订号 9869421"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/xunzi/chapter-01.md","filePath":"lizhimingde/xunzi/chapter-01.md","lastUpdated":1794362429000}'),m={name:"lizhimingde/xunzi/chapter-01.md"},c=g({...m,setup(x){const s=[{id:"p001",label:"学不可以已",showLabel:!0,sentences:[[{text:"君子",glossary:"junzi"},"曰：学不可以",{text:"已",glossary:"yi"},"。青，取之于",{text:"蓝",glossary:"lan"},"而青于",{text:"蓝",glossary:"lan"},"；冰，水为之而寒于水。木直",{text:"中绳",glossary:"zhongsheng"},"，",{text:"𫐓",glossary:"rou"},"以为轮，其曲中规，虽有",{text:"槁暴",glossary:"gaopu"},"，不复挺者，",{text:"𫐓",glossary:"rou"},"使之然也。故木受绳则直，金就",{text:"砺",glossary:"li"},"则利，",{text:"君子",glossary:"junzi"},"博学而日",{text:"参省",glossary:"canxing"},"乎己，则",{text:"知",glossary:"zhi"},"明","而行无过矣。"]],note:"君子说，学习不能停止。靛青从蓝草提取，却比蓝草更青；冰由水凝成，却比水更冷。笔直的木材经过煣曲，可以成为合乎圆规的车轮；即使再晒干，也不再挺直。木材经墨线校正而直，金属经磨砺而锋利。人也应广泛学习，每日检查反省自己，使认识明达、行为减少过失。这里借加工变化说明学习能够改变人，不只是在赞扬天资。"},{id:"p002",label:"见闻与教化",showLabel:!0,sentences:[["故不登高山，不知天之高也；不临深谿，不知地之厚也；不闻先王之遗言，不知学问之大也。于、越、夷、",{text:"貉",glossary:"he"},"之子，生而同声，长而异俗，教使之然也。《诗》曰：“嗟尔",{text:"君子",glossary:"junzi"},"，无恒安息。",{text:"靖共",glossary:"jinggong"},"尔位，好是正直。神之听之，介尔",{text:"景福",glossary:"jingfu"},"。”神莫大于化道，福莫长于无祸。"]],note:"不登高山、不临深谷，就难以体会天地的高厚；不接触先王留下的言论，也难知学习的广大。不同地域的孩子初生啼声相近，长大后风俗各异，说明教养与环境的作用。《诗》劝君子不要贪图安逸，应恭谨尽职、爱好正直。荀子接着说，最神妙的效验在于受道的化育，长久的福分在于免于祸患。这是古人的劝学论证，不是勤学必然免灾的现实保证。"},{id:"p003",label:"善假于物",showLabel:!0,sentences:[["吾尝终日而思矣，不如",{text:"须臾",glossary:"xuyu"},"之所学也，吾尝",{text:"跂",glossary:"qi"},"而望矣，不如登高之博见也。登高而招，臂非加长也，而见者远；顺风而呼，声非加疾也，而闻者彰。",{text:"假",glossary:"jia"},"舆马者，非利足也，而致千里；",{text:"假",glossary:"jia"},"舟",{text:"楫",glossary:"ji"},"者，非能水也，而绝江河。",{text:"君子",glossary:"junzi"},{text:"生",glossary:"xing"},"非异","也，善",{text:"假",glossary:"jia"},"于物也。"]],note:"我曾整日思索，却不如片刻学习所得；踮脚远望，也不如登高看得广。登高招手、顺风呼喊，身体与声音并未变强，却能传得更远。借助车马可以远行，借助舟船可以渡水，都不靠天生的特殊本领。君子与别人并非生性截然不同，关键在善于利用条件。这里并不取消思考，而是提醒思考也需要见闻、工具和方法。"},{id:"p004",label:"择其所处",showLabel:!0,sentences:[["南方有鸟焉，名曰",{text:"蒙鸠",glossary:"mengjiu"},"，以羽为巣而编之以髮，繫之苇苕，风至苕折，卵破子死。巣非不完也，所繫者然也。西方有木焉，名曰",{text:"射干",glossary:"yegan"},"，茎长四寸，生于高山之上，而临百仞之渊，木茎非能长也，所立者然也。蓬生麻中，不扶而直。兰槐之根是为芷。其",{text:"渐",glossary:"jian"},"之",{text:"滫",glossary:"xiu"},"，",{text:"君子",glossary:"junzi"},"不近，庶人不服，其质非不美也，所",{text:"渐",glossary:"jian"},"者然也。故",{text:"君子",glossary:"junzi"},"居必择乡，遊必就士，所以防邪僻而近中正也。"]],note:"蒙鸠的巢编织得牢固，却系在易折的芦苇穗上，风来仍会毁巢伤卵；射干茎短，却因生在高山而俯临深渊。蓬草生在麻丛中，不扶也直；香草之根虽好，浸入污水也会令人避开。事物自身的条件之外，安放何处、受到什么熏染同样重要。所以君子要选择居处与交游对象，远离邪僻而接近中正。鸟名、草木名沿用古说，不强定为现代生物分类。"},{id:"p005",label:"慎其所立",showLabel:!0,sentences:[["物类之起，必有所始。荣辱之来，必象其德。肉腐出蟲，鱼枯生蠹。怠慢忘身，祸灾乃作。强自取柱，柔自取束。邪秽在身，怨之所构。施薪若一，火就燥也；平地若一，水就湿也。草木畴生，禽兽群焉，物各从其类也。是故",{text:"质的",glossary:"zhidi"},"张而弓矢至焉，林木茂而斧斤至焉，树成荫而众鸟息焉，酰酸而",{text:"蜹",glossary:"rui"},"聚焉。故言有召祸也，行有招辱也，",{text:"君子",glossary:"junzi"},"慎其所立乎！"]],note:"荀子用腐肉生虫、干柴易燃、湿地聚水以及箭靶引箭等比喻，说明行为与所处条件会招来相应后果。人的言语可能招祸，举动可能取辱，因此要谨慎选择自己的立足之处。文中把荣辱联系到德行，是修身上的劝诫；不能据此倒推现实中每个受害者都该为遭遇负责。腐肉生虫等说法也属于古人的观察与解释，不作为现代科学知识。"},{id:"p006",label:"积累与不舍",showLabel:!0,sentences:[["积土成山，风雨兴焉；积水成渊，蛟龙生焉；积善成德，而神明自得，圣心备焉。故不积",{text:"跬步",glossary:"kuibu"},"，无以至千里；不积小流，无以成江海。",{text:"骐骥",glossary:"qiji"},"一跃，不能十步；",{text:"驽马",glossary:"numa"},"十驾，功在不舍。",{text:"锲",glossary:"qie"},"而舍之，朽木不折；",{text:"锲",glossary:"qie"},"而不舍，金石可",{text:"镂",glossary:"lou"},"。"]],note:"土、水不断积聚，可以成为山与深渊；善行不断积聚，才逐渐形成德性和判断力。不积小步，不能远行；不积细流，不能成江海。良马一跃也难走远，劣马持续拉车却能建立功效。刻一下就放弃，朽木也刻不断；坚持雕刻，金石也能留下纹饰。重点是持续积累，不是把短期速度当作学习的全部。"},{id:"p007",label:"用心一也",showLabel:!0,sentences:[["蚓无爪牙之利，筋骨之强，上食埃土，下饮黄泉，用心一也。蟹六跪而二",{text:"螯",glossary:"ao"},"，非蛇鳝之穴无可寄託者，用心",{text:"躁",glossary:"zao"},"也。是故无冥冥之志者无昭昭之明，无惛惛之事者无赫赫之功。行衢道者不至，事两君者不容。目不能两视而明，耳不能两听而聪。",{text:"螣蛇",glossary:"tengshe"},"无足而飞，",{text:"梧鼠",glossary:"wushu"},"五技而穷。《诗》曰：“尸鸠在桑，其子七兮。淑人",{text:"君子",glossary:"junzi"},"，其仪一兮。其仪一兮，心如结兮。”故",{text:"君子",glossary:"junzi"},"结于一也。"]],note:"蚯蚓没有锋利爪牙和强健筋骨，却能在土中生存，荀子以此说明用心专一；螃蟹有足有螯，却借别的洞穴栖身，被用来反衬用心躁散。深厚志向、切实积累与显著成效相连；心思分岔，力量就难集中。螣蛇与梧鼠、诗中的尸鸠，又把论证引回守一。原文的蟹足数量和动物传说保留为古代比喻，不据此讲现代动物学。"},{id:"p008",label:"积善而后显",showLabel:!0,sentences:[["昔者",{text:"瓠巴",glossary:"huba"},"鼓瑟而流鱼出听，伯牙鼓琴而六马",{text:"仰秣",glossary:"yangmo"},"。故声无小而不闻，行无隐而不形；玉在山而草木润，渊生珠而崖不枯。为善不积邪，安有不闻者乎？"]],note:"古人传说瓠巴、伯牙奏乐，鱼与马也会有所感应；声音虽小、行为虽隐，也可能被听见、显露。玉藏山中使草木润泽，渊中生珠使崖岸不枯，都是用来说明内在积累与外在表现相通的比喻。善行若真正积累，何愁完全没有表现？这里的音乐感应与珠玉润物属于寓喻，不能把它解成积善便一定获得名声或回报。"},{id:"p009",label:"为学的次第与目标",showLabel:!0,sentences:[["学恶乎始？恶乎终？曰：其数则始乎诵经，终乎读礼；其义则始乎为士，终乎为圣人。真积力久则入，学至乎",{text:"没",glossary:"mo"},"而后止也。故",{text:"学数",glossary:"xueshu"},"有终，若其义则不可",{text:"须臾",glossary:"xuyu"},"舍也。为之，人也；舍之，禽兽也。故《书》者，政事之纪也；《诗》者，中声之所止也；《礼》者，法之大分，类之纲纪也。故学至乎《礼》而止矣。夫是之谓道德之极。《礼》之敬文也，《乐》之中和也，《诗》、《书》之博也，《春秋》之微也，在天地之间者毕矣。"]],note:"学习从哪里开始，到哪里结束？就课程次第说，从诵读经典到研读礼；就意义说，从做一个士到成就圣人。真诚积累、长久实践，才能深入，直到生命终结才停止。因此课程可以有阶段终点，修养却不能片刻丢开。文中依次说明《书》记政事、《诗》节声音、《礼》立纲纪，并将礼视为统摄学习的关键。这里的圣人与礼，是荀子自己的规范目标，不等于今天所有学习都必须依其制度。"},{id:"p010",label:"为己之学",showLabel:!0,sentences:[[{text:"君子",glossary:"junzi"},"之学也，入乎耳，",{text:"箸",glossary:"zhu"},"乎心，布乎四体，形乎动静，端而言，",{text:"蝡",glossary:"ru"},"而动，一可以为法则。小人之学也，入乎耳，出乎口。口耳之间则四寸耳，曷足以美七尺之躯哉！古之学者",{text:"为己",glossary:"weiji"},"，今之学者",{text:"为人",glossary:"weiren"},"。",{text:"君子",glossary:"junzi"},"之学也，以美其身；小人之学也，以为",{text:"禽犊",glossary:"qindu"},"。"]],note:"君子所学从耳进入，留在心里，贯彻到四肢，表现在言行举止中；小人所学却听过便说，止于口耳。古人学习重在成就自己，时人却常为让别人看见。君子用学习修养自身，小人把它当作求取赏识的礼物。这里的为己不是只顾私利，为人也不是替人服务，而是为了他人的评价而展示所学。"},{id:"p011",label:"言说要有分寸",showLabel:!0,sentences:[["故不问而告谓之傲，问一而告二谓之",{text:"囋",glossary:"za"},"。傲、非也；",{text:"囋",glossary:"za"},"，非也；",{text:"君子",glossary:"junzi"},"如",{text:"向",glossary:"xiang"},"矣。"]],note:"别人没有问便径自宣说，叫作傲；问一件却铺陈两件、过量炫说，叫作囋。君子应如回声相应，有所问而恰当回应。这一小节把为己之学落实到交流：有学问不等于随时占满他人的注意力，还要照顾对方真正的问题与接受的分寸。"},{id:"p012",label:"亲近可学习的人",showLabel:!0,sentences:[["学莫便乎",{text:"近其人",glossary:"jinqiren"},"。《礼》、《乐》法而不说，《诗》、《书》故而不切，《春秋》约而不速。方其人之习",{text:"君子",glossary:"junzi"},"之说，则尊以遍矣，周于世矣。故曰学莫便乎",{text:"近其人",glossary:"jinqiren"},"。"]],note:"学习最便利的途径，是接近能体现所学的人。经典虽有法度、旧事与精要文字，却不总能直接解释眼前每一个问题；亲近君子，听其说明、观察其习行，可以使理解更完整，并与现实相接。荀子由此再次强调亲师取友。亲近其人不必解释成盲从个人，而应看他如何把原则落实在行为中。"},{id:"p013",label:"隆礼以贯通所学",showLabel:!0,sentences:[["学之经莫速乎好其人，",{text:"隆礼",glossary:"longli"},"次之。上不能好其人，下不能",{text:"隆礼",glossary:"longli"},"，安特将学杂识志，顺《诗》、《书》而","已","耳，则末世穷年，不免为陋儒而","已","。将原先王，本仁义，则礼正其经纬蹊径也。若挈裘领，诎五指而顿之，顺者不可胜数也。不道礼宪，以《诗》、《书》为之，譬之犹以指测河也，以戈舂黍也，以锥餐壶也，不可以得之矣。故",{text:"隆礼",glossary:"longli"},"，虽未明，法士也；不",{text:"隆礼",glossary:"longli"},"，虽察辩，散儒也。"]],note:"为学的要径，先在敬爱可作榜样的人，其次在尊重礼的统摄作用。若只杂记零碎知识、顺读《诗》《书》，终年也可能局促不通。荀子用提衣领便能整理皮裘作比，说明抓住仁义和礼的纲领才能理顺细目；缺少统摄，只靠零星字句，就像用手指量河、用兵器舂米，工具与任务不相应。这里的隆礼应放回先秦儒学语境，不直接照搬古代等级秩序。"},{id:"p014",label:"论辩的条件",showLabel:!0,sentences:[["问",{text:"楛",glossary:"ku"},"者勿告也，告",{text:"楛",glossary:"ku"},"者勿问也，说",{text:"楛",glossary:"ku"},"者勿听也，有争气者勿与辩也。故必由其道至，然后接之，非其道则避之。故礼恭而后可与言道之方，辞顺而后可与言道之理，色从而后可与言道之致。故未可与言而言谓之傲，可与言而不言谓之隐，不观气色而言谓之",{text:"瞽",glossary:"gu"},"。故",{text:"君子",glossary:"junzi"},"不傲，不隐，不",{text:"瞽",glossary:"gu"},"，谨顺其身。《诗》曰：“匪交匪舒，天子所予。”此之谓也。"]],note:"对于失当的提问、言说和只争意气的争辩，不必贸然卷入；交流应先有合宜的态度与路径。能够恭敬、言辞顺当、神色相应，才更可能谈清方向、义理与细节。不适合谈却强谈，是傲；可以谈却不谈，是隐；不看对方神色便说，是瞽。君子应避免这三种失当。今天借鉴的是交流须顾对象与情境，不以此拒绝一切异议。"},{id:"p015",label:"贯通与一致",showLabel:!0,sentences:[["百发失一，不足谓善射；千里",{text:"跬步",glossary:"kuibu"},"不至，不足谓善御；",{text:"伦类",glossary:"lunlei"},"不通，仁义不一，不足谓善学。学也者，固学一之也。一出焉，一入焉，涂巷之人也。其善者少，不善者多，桀、纣、盗跖也。全之尽之，然后学者也。"]],note:"荀子用射箭、驾车的精熟作比，要求学习能够贯通事类，并在仁义上保持一致。时而进入、时而退出，或善行少而恶行多，都不算真正成就学习。全之尽之，强调所知与所行不彼此割裂；不宜把这个高标准变成一次犯错便全盘否定自己或他人的完美主义。"},{id:"p016",label:"能定能应",showLabel:!0,sentences:[[{text:"君子",glossary:"junzi"},"知夫不全不粹之不足以为美也，故诵数以贯之，思索以通之，为其人以处之，除其害者以持养之，使目非是无欲见也，使耳非是无欲闻也，使口非是无欲言也，使心非是无欲虑也。及至其致好之也，目好之五色，耳好之五声，口好之五味，心利之有天下。是故权利不能倾也，群众不能移也，天下不能荡也。生乎由是，死乎由是，夫是之谓",{text:"德操",glossary:"decao"},"。",{text:"德操",glossary:"decao"},"然后能定，能定然后能应，能定能应，夫是之谓成人。天见其明，地见其光，",{text:"君子",glossary:"junzi"},"贵其全也。"]],note:"君子以反复诵习贯通所学，以思考探求其意，与合宜的人相处，并去除妨害以持续涵养。长久之后，对所学的爱好逐渐深切，不再轻易被权势、利诱、众人或天下的变动摇。无论生死都守住所学的道路，叫作德操；有德操才能安定，有安定才能恰当应事，这才是人格的成熟。结尾借天地显明，强调君子贵在完整。关于五色、五声等句，古注另有不同理解，此处取以所学为深切爱好的串讲。"}],n=[{id:"junzi",term:"君子",sense:1},{id:"yi",term:"已",sense:1},{id:"lan",term:"蓝",pinyin:"lán",meaning:"可以提取靛青的蓝草。这里指染料植物，不是颜色名称。"},{id:"rou",term:"𫐓",pinyin:"róu",meaning:"同輮，以火烘木使之弯曲。保留所据简体显示录文的字形。"},{id:"zhongsheng",term:"中绳",pinyin:"zhòng shéng",meaning:"合乎墨线所定的直度。中读zhòng，意为符合。"},{id:"gaopu",term:"槁暴",pinyin:"gǎo pù",meaning:"枯干、晒干。暴通曝，读pù；有通又。"},{id:"li",term:"砺",pinyin:"lì",meaning:"磨刀石。金就砺，即金属刀具拿到磨石上磨砺。"},{id:"canxing",term:"参省",pinyin:"cān xǐng",meaning:"检查、反省。参有检验之义；古注另以参为三，联系每日多次省察。"},{id:"zhi",term:"知",sense:3,pinyin:"zhì"},{id:"he",term:"貉",pinyin:"mò",meaning:"古代对东北某些族群的称谓，读mò。这里与于、越、夷并列，不指现代动物貉。"},{id:"jinggong",term:"靖共",pinyin:"jìng gōng",meaning:"恭谨地尽职。共通恭；古注训靖为谋，理解为谋虑并恭守其职。"},{id:"jingfu",term:"景福",pinyin:"jǐng fú",meaning:"大福。景训大；介尔景福，意为助你获得大福。"},{id:"xuyu",term:"须臾",sense:1},{id:"qi",term:"跂",pinyin:"qǐ",meaning:"踮起脚后跟，以便望得更远。"},{id:"jia",term:"假",sense:1},{id:"ji",term:"楫",pinyin:"jí",meaning:"船桨，舟楫合指船只等渡水工具。"},{id:"xing",term:"生",pinyin:"xìng",meaning:"君子生非异也中的生通性，指天生的禀性。只标本句，其他生字仍按各自语境理解。"},{id:"mengjiu",term:"蒙鸠",pinyin:"méng jiū",meaning:"古代鸟名，旧注多释为鹪鹩一类的小鸟。文中用其系巢于芦苇作比，不强定现代物种。"},{id:"yegan",term:"射干",pinyin:"yè gān",meaning:"古代植物名，射读yè。文中强调它因立于高处而俯临深渊，具体植物指称旧注有疑。"},{id:"jian",term:"渐",pinyin:"jiān",meaning:"浸渍、浸染。其渐之滫，指把香草之根浸入污浊的水中；不读表示逐渐的jiàn。"},{id:"xiu",term:"滫",pinyin:"xiǔ",meaning:"污浊的水，旧注释作溺，也有臭泔水等说法。这里用来说明不良环境的熏染。"},{id:"zhidi",term:"质的",pinyin:"zhì dì",meaning:"箭靶。质指射侯，的指靶心；的读dì。"},{id:"rui",term:"蜹",pinyin:"ruì",meaning:"小飞虫，常与蚋相通。酰酸而蜹聚，以酸醋招虫作比。"},{id:"kuibu",term:"跬步",sense:1},{id:"qiji",term:"骐骥",pinyin:"qí jì",meaning:"良马、骏马。文中与驽马对照，说明一次跃进不能替代持续行走。"},{id:"numa",term:"驽马",pinyin:"nú mǎ",meaning:"跑得慢、能力较弱的马。十驾指持续多日驾车，不是一次套上十匹马。"},{id:"qie",term:"锲",sense:1},{id:"lou",term:"镂",pinyin:"lòu",meaning:"雕刻。金石可镂，以难刻之物也能留下纹饰比喻坚持之效。"},{id:"ao",term:"螯",pinyin:"áo",meaning:"蟹等动物的大钳。跪在此指蟹足；原文六跪的数量属于所据古文，不作为现代动物学描述。"},{id:"zao",term:"躁",sense:1},{id:"tengshe",term:"螣蛇",pinyin:"téng shé",meaning:"传说中能飞的蛇。用来与梧鼠对照，说明本领多寡之外还要看能否专一。"},{id:"wushu",term:"梧鼠",pinyin:"wú shǔ",meaning:"旧注常与鼫鼠相联系，传说有五种本领而各不精。具体动物指称有异说。"},{id:"huba",term:"瓠巴",pinyin:"hù bā",meaning:"古代传说中善于鼓瑟的人。此处与伯牙并举，以乐声感物比喻内在修养的显现。"},{id:"yangmo",term:"仰秣",pinyin:"yǎng mò",meaning:"马仰头听琴而停食、或仰头作食状，旧说有别。秣为饲草；此处是音乐感物的传说。"},{id:"xueshu",term:"学数",pinyin:"xué shù",meaning:"学习的课程、程序与次第。与下文终身修养的意义相区别，数读shù。"},{id:"mo",term:"没",pinyin:"mò",meaning:"终没、死亡，通殁。学至乎没而后止，指学习终身不息。"},{id:"zhu",term:"箸",pinyin:"zhù",meaning:"同著，附着、留存。箸乎心，指所学真正留在心中。"},{id:"ru",term:"蝡",pinyin:"rú",meaning:"蠕动、微动。蝡而动，指细微的举动。"},{id:"weiji",term:"为己",sense:1},{id:"weiren",term:"为人",sense:2},{id:"qindu",term:"禽犊",pinyin:"qín dú",meaning:"禽鸟与小牛，古代可作馈赠之礼。这里比喻把学问当成求取赏识、进见的礼物。"},{id:"za",term:"囋",pinyin:"zá",meaning:"多言、炫说。本页据汉典多言义读zá，另有zàn读法；古注将它与赞字相通。问一而告二，批评不顾所问而过量铺陈。"},{id:"xiang",term:"向",pinyin:"xiàng",meaning:"通响，回声。君子如向，指言说如回声般因问作答、恰当相应。"},{id:"jinqiren",term:"近其人",pinyin:"jìn qí rén",meaning:"亲近能体现所学的师长、君子，观察其行并听其说明。其人不泛指有权势的人。"},{id:"longli",term:"隆礼",pinyin:"lóng lǐ",meaning:"尊崇礼，重视礼义的统摄与实践。须放在荀子以礼组织学习和社会秩序的语境中理解。"},{id:"ku",term:"楛",pinyin:"kǔ",meaning:"粗恶、失当。问楛、告楛、说楛，指内容或方式失当的问答言说。"},{id:"gu",term:"瞽",pinyin:"gǔ",meaning:"本指盲人，这里比喻不察情境便贸然言说。所批评的是交流失当，不以身体状况评判人格。"},{id:"lunlei",term:"伦类",pinyin:"lún lèi",meaning:"事物的条理与类别。伦类不通，指不能贯通、类推所学。"},{id:"decao",term:"德操",pinyin:"dé cāo",meaning:"德行与操守。文中指在生死、权利与群体压力面前仍能持守所学之道。"}];return(y,e)=>{const l=t("DaoTextReading"),o=t("DaoKeywordCards");return h(),d("div",null,[e[0]||(e[0]=a("h1",{id:"荀子·第1篇·劝学",tabindex:"-1"},[i("荀子·第1篇·劝学 "),a("a",{class:"header-anchor",href:"#荀子·第1篇·劝学","aria-label":'Permalink to "荀子·第1篇·劝学"'},"​")],-1)),e[1]||(e[1]=a("p",null,"本篇讨论：学习如何改变人，怎样积累、专一并落实于行为。全文不止于「锲而不舍」，还讨论环境、师友、学习的目的与交流分寸。",-1)),e[2]||(e[2]=a("p",null,"本页为首轮整理，待作者审读。下列十六段按论意重新划分，段题为整理者所加；并非原书自有的小章。",-1)),e[3]||(e[3]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),e[4]||(e[4]=a("p",null,"经典阅读保留段落；切换「竹简」可连续通读。经典阅读中可点字词查音义，并打开段级释义。",-1)),r(l,{sections:s,glossary:n,"default-mode":"classic",tone:"ink",colophon:"荀子 · 劝学","aria-label":"荀子·劝学原文"}),e[5]||(e[5]=a("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[i("【原典层】注音与字词 "),a("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),r(o,{items:n}),e[6]||(e[6]=u("",52))])}}});export{b as __pageData,c as default};
